// Define a simple Matrix struct to hold the result
#[derive(Debug, PartialEq)]
pub struct Matrix<T> {
    data: Vec<Vec<T>>,
    rows: usize,
    cols: usize,
}

impl<T> Matrix<T> {
    // Helper method to create a new matrix
    fn new(data: Vec<Vec<T>>, rows: usize, cols: usize) -> Self {
        Matrix { data, rows, cols }
    }
}

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract dimensions from shape
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    // Get the length of the input array
    let len = a.len();
    
    // Check which dimension matches the array length
    if len == r {
        // Array length equals number of rows: treat as column vector
        // Each row gets the same element repeated across all columns
        let mut matrix_data = Vec::with_capacity(r);
        
        for i in 0..r {
            let row_value = a[i];
            let row = vec![row_value; c]; // Create a row with c copies of a[i]
            matrix_data.push(row);
        }
        
        Matrix::new(matrix_data, r, c)
    } else if len == c {
        // Array length equals number of columns: treat as row vector
        // Each row gets a copy of the entire array
        let mut matrix_data = Vec::with_capacity(r);
        
        for _ in 0..r {
            let row = a.clone(); // Clone the entire array for each row
            matrix_data.push(row);
        }
        
        Matrix::new(matrix_data, r, c)
    } else {
        // According to the problem statement, this case shouldn't happen
        // because one dimension must match, but we'll handle it defensively
        panic!("Array length must match either rows or columns");
    }
}